package com.bookstore.service;
import com.bookstore.entity.*; import com.bookstore.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CartService { private final CartRepository cart; private final BookRepository books; public CartService(CartRepository c,BookRepository b){cart=c;books=b;} public List<CartItem> items(User u){return cart.findByUser(u);} public void add(User u,Long bid,int q){Book b=books.findById(bid).orElseThrow(); if(q<1)q=1; if(q>b.getStock()) throw new IllegalArgumentException("Not enough stock"); CartItem x=cart.findByUserAndBook(u,b).orElse(new CartItem(u,b,0)); x.setQuantity(x.getQuantity()+q); if(x.getQuantity()>b.getStock())x.setQuantity(b.getStock()); cart.save(x);} public void remove(Long id){cart.deleteById(id);} public double total(User u){return items(u).stream().mapToDouble(x->x.getBook().getPrice()*x.getQuantity()).sum();} public void clear(User u){cart.deleteByUser(u);} }
